/* DAWAH X — ahmad, অধ্যায় 69 · খণ্ড 69 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][69]=[[13601,13601,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏غَزَوْنَا ‏ ‏أَوْ سَافَرْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ يَوْمَئِذٍ بِضْعَةَ عَشَرَ وَمِائَتَانِ فَحَضَرَتْ الصَّلَاةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ فِي الْقَوْمِ مِنْ مَاءٍ فَجَاءَ رَجُلٌ ‏ ‏يَسْعَى ‏ ‏بِإِدَاوَةٍ ‏ ‏فِيهَا شَيْءٌ مِنْ مَاءٍ قَالَ فَصَبَّهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَدَحٍ قَالَ ‏ ‏فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَحْسَنَ الْوُضُوءَ ثُمَّ انْصَرَفَ وَتَرَكَ الْقَدَحَ فَرَكِبَ النَّاسُ الْقَدَحَ يَمْسَحُوا وَيَمْسَحُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رِسْلِكُمْ حِينَ سَمِعَهُمْ يَقُولُونَ ذَلِكَ قَالَ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَّهُ فِي الْمَاءِ وَالْقَدَحِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسْمِ اللَّهِ ثُمَّ قَالَ أَسْبِغُوا الْوُضُوءَ فَوَالَّذِي هُوَ ابْتَلَانِي بِبَصَرِي لَقَدْ رَأَيْتُ الْعُيُونَ عُيُونَ الْمَاءِ يَوْمَئِذٍ تَخْرُجُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَوَضَّئُوا أَجْمَعُونَ ‏","","",""],[13602,13602,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهِلِّينَ ‏ ‏بِالْحَجِّ مَعَنَا النِّسَاءُ وَالْوِلْدَانُ فَلَمَّا قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏طُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ فَلْيَحْلِلْ قُلْنَا أَيُّ الْحِلِّ قَالَ الْحِلُّ كُلُّهُ قَالَ ‏ ‏فَأَتَيْنَا ‏ ‏النِّسَاءَ وَلَبِسْنَا الثِّيَابَ وَمَسِسْنَا الطِّيبَ فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏أَهْلَلْنَا بِالْحَجِّ وَكَفَانَا الطَّوَافُ الْأَوَّلُ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَأَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَشْتَرِكَ فِي الْإِبِلِ ‏ ‏وَالْبَقَرِ كُلُّ سَبْعَةٍ مِنَّا فِي بَدَنَةٍ فَجَاءَ ‏ ‏سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ بَيِّنْ لَنَا دِينَنَا كَأَنَّا خُلِقْنَا الْآنَ أَرَأَيْتَ عُمْرَتَنَا هَذِهِ لِعَامِنَا هَذَا أَمْ لِلْأَبَدِ فَقَالَ لَا بَلْ لِلْأَبَدِ قَالَ يَا رَسُولَ اللَّهِ بَيِّنْ لَنَا دِينَنَا كَأَنَّا خُلِقْنَا الْآنَ فِيمَا الْعَمَلُ الْيَوْمَ أَفِيمَا جَفَّتْ بِهِ الْأَقْلَامُ وَجَرَتْ بِهِ الْمَقَادِيرُ ‏ ‏أَوْ فِيمَا نَسْتَقْبِلُ قَالَ لَا بَلْ فِيمَا جَفَّتْ بِهِ الْأَقْلَامُ وَجَرَتْ بِهِ الْمَقَادِيرُ ‏ ‏قَالَ فَفِيمَ الْعَمَلُ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فِي حَدِيثِهِ ‏ ‏فَسَمِعْتُ ‏ ‏مَنْ سَمِعَ ‏ ‏مِنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏يَقُولُ قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏فَسَأَلْتُ ‏ ‏يَاسِينَ ‏ ‏مَا قَالَ قَالَ ثُمَّ لَمْ أَفْهَمْ كَلَامًا تَكَلَّمَ بِهِ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏فَسَأَلْتُ ‏ ‏رَجُلًا ‏ ‏فَقُلْتُ كَيْفَ قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏فِي هَذَا الْمَوْضِعِ فَقَالَ سَمِعْتُهُ يَقُولُ ‏ ‏اعْمَلُوا فَكُلٌّ مُيَسَّرٌ ‏","","",""],[13603,13603,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏غُولَ ‏","","",""],[13604,13604,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا انْقَطَعَ ‏ ‏شِسْعُ ‏ ‏أَحَدِكُمْ فَلَا يَمْشِ فِي نَعْلٍ وَاحِدَةٍ حَتَّى يُصْلِحَ ‏ ‏شِسْعَهُ ‏ ‏وَلَا يَمْشِ فِي ‏ ‏خُفٍّ ‏ ‏وَاحِدَةٍ وَلَا يَأْكُلْ بِشِمَالِهِ وَلَا ‏ ‏يَحْتَبِ ‏ ‏بِالثَّوْبِ الْوَاحِدِ وَلَا ‏ ‏يَلْتَحِفُ ‏ ‏الصَّمَّاءَ ‏","","",""],[13605,13605,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي كَرِبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ إِلَى خَشَبَةٍ فَلَمَّا جُعِلَ مِنْبَرٌ حَنَّتْ حَنِينَ النَّاقَةِ إِلَى وَلَدِهَا فَأَتَاهَا فَوَضَعَ يَدَهُ عَلَيْهَا فَسَكَنَتْ ‏","","",""],[13606,13606,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏","","",""],[13607,13607,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ أَوْ يَمْشِيَ فِي نَعْلٍ وَاحِدَةٍ أَوْ ‏ ‏يَحْتَبِ ‏ ‏بِثَوْبٍ وَاحِدٍ أَوْ ‏ ‏يَشْتَمِلَ ‏ ‏الصَّمَّاءَ ‏","","",""],[13608,13608,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَشْعَثَ بْنَ سَوَّارٍ ‏ ‏عِنْدَ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏قَائِمًا وَهُوَ يَقُولُ ‏ ‏كَيْفَ قَالَ ‏ ‏وَإِيشِ قَالَ ‏","","",""],[13609,13609,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ الْمُقَدَّمُ وَشَرُّهَا الْمُؤَخَّرُ وَشَرُّ صُفُوفِ النِّسَاءِ الْمُقَدَّمُ وَخَيْرُهَا الْمُؤَخَّرُ ثُمَّ قَالَ يَا مَعْشَرَ النِّسَاءِ إِذَا سَجَدَ الرِّجَالُ فَاغْضُضْنَ أَبْصَارَكُنَّ لَا تَرَيْنَ عَوْرَاتِ الرِّجَالِ مِنْ ضِيقِ ‏ ‏الْأُزُرِ ‏","","",""],[13610,13610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْحُبُلِيَّ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏بَرَكَ بِهِ بَعِيرٌ قَدْ ‏ ‏أَزْحَفَ ‏ ‏بِهِ فَمَرَّ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ مَا لَكَ يَا ‏ ‏جَابِرُ ‏ ‏فَأَخْبَرَهُ فَنَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْبَعِيرِ ثُمَّ قَالَ ارْكَبْ يَا ‏ ‏جَابِرُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُ لَا يَقُومُ فَقَالَ لَهُ ارْكَبْ فَرَكِبَ ‏ ‏جَابِرٌ ‏ ‏الْبَعِيرَ ثُمَّ ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَعِيرَ بِرِجْلِهِ ‏ ‏فَوَثَبَ ‏ ‏الْبَعِيرُ ‏ ‏وَثْبَةً ‏ ‏لَوْلَا أَنَّ ‏ ‏جَابِرًا ‏ ‏تَعَلَّقَ بِالْبَعِيرِ لَسَقَطَ مِنْ فَوْقِهِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِجَابِرٍ ‏ ‏تَقَدَّمْ يَا ‏ ‏جَابِرُ ‏ ‏الْآنَ عَلَى أَهْلِكَ إِنْ شَاءَ اللَّهُ تَعَالَى تَجِدْهُمْ قَدْ يَسَّرُوا لَكَ كَذَا وَكَذَا حَتَّى ذَكَرَ الْفُرُشَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرَاشٌ لِلرَّجُلِ وَفِرَاشٌ لِامْرَأَتِهِ وَالثَّالِثُ لِلضَّيْفِ وَالرَّابِعُ لِلشَّيْطَانِ ‏","","",""],[13611,13611,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ مَوْتِهِ بِثَلَاثٍ يَقُولُ ‏ ‏لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ بِاللَّهِ الظَّنَّ ‏","","",""],[13612,13612,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُعْطُوهَا أَحَدًا فَمَنْ ‏ ‏أُعْمِرَ ‏ ‏شَيْئًا فَهُوَ لَهُ ‏","","",""],[13613,13613,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَحَرْنَا ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَدَنَةَ ‏ ‏عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ ‏","","",""],[13614,13614,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيُوتِرْ ‏","","",""],[13615,13615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَيْ ‏ ‏جَابِرٍ ‏ ‏يُحَدِّثَانِ عَنْ ‏ ‏أَبِيهِمَا ‏ ‏قَالَ ‏ ‏بَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ مَعَ أَصْحَابِهِ شَقَّ قَمِيصَهُ حَتَّى خَرَجَ مِنْهُ فَقِيلَ لَهُ فَقَالَ ‏ ‏وَاعَدْتُهُمْ ‏ ‏يُقَلِّدُونَ ‏ ‏هَدْيًا ‏ ‏الْيَوْمَ فَنَسِيتُ ‏","","",""],[13616,13616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَا ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَتَقَدَّمَ رِجَالٌ ‏ ‏فَنَحَرُوا ‏ ‏وَظَنُّوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏نَحَرَ ‏ ‏فَأَمَرَ مَنْ كَانَ قَدْ ‏ ‏نَحَرَ ‏ ‏قَبْلَهُ أَنْ يُعِيدَ بِنَحْرٍ آخَرَ وَلَا وَلِيَنْحَرْ حَتَّى يَنْحَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13617,13617,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏الْعُمْرَى ‏ ‏الَّتِي أَجَازَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقُولَ ‏ ‏هِيَ لَكَ ‏ ‏وَلِعَقِبِكَ ‏ ‏فَأَمَّا إِذَا قَالَ هِيَ لَكَ مَا عِشْتَ فَإِنَّهَا تَرْجِعُ إِلَى صَاحِبِهَا ‏","","",""],[13618,13618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَزَوَّجْتَ فَقُلْتُ نَعَمْ فَقَالَ ‏ ‏أَبِكْرًا ‏ ‏أَمْ ‏ ‏ثَيِّبًا ‏ ‏فَقُلْتُ لَا بَلْ ‏ ‏ثَيِّبًا ‏ ‏لِي أَخَوَاتٌ وَعَمَّاتٌ فَكَرِهْتُ أَنْ أَضُمَّ إِلَيْهِنَّ ‏ ‏خَرْقَاءَ ‏ ‏مِثْلَهُنَّ قَالَ أَفَلَا ‏ ‏بِكْرًا ‏ ‏تُلَاعِبُهَا قَالَ لَكُمْ ‏ ‏أَنْمَاطٌ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ وَأَنَّى فَقَالَ ‏ ‏خَفْ أَمَا إِنَّهَا سَتَكُونُ لَكُمْ ‏ ‏أَنْمَاطٌ ‏ ‏فَأَنَا الْيَوْمَ أَقُولُ لِامْرَأَتِي نَحِّي عَنِّي ‏ ‏أَنْمَاطَكِ ‏ ‏فَتَقُولُ نَعَمْ أَلَمْ يَقُلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ لَكُمْ ‏ ‏أَنْمَاطٌ ‏ ‏فَأَتْرُكُهَا ‏","","",""],[13619,13619,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَعْتَقَ رَجُلٌ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامًا لَهُ لَيْسَ لَهُ مَالٌ غَيْرُهُ عَلَى ‏ ‏دُبُرٍ ‏ ‏مِنْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يَبْتَاعُهُ ‏ ‏مِنِّي فَقَالَ ‏ ‏نُعَيْمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَا ‏ ‏أَبْتَاعُهُ ‏ ‏فَابْتَاعَهُ ‏ ‏فَقَالَ ‏ ‏عَمْرٌو ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏غُلَامٌ قِبْطِيٌّ وَمَاتَ عَامَ الْأَوَّلِ ‏ ‏زَادَ فِيهَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏يُقَالُ لَهُ ‏ ‏يَعْقُوبُ ‏","","",""],[13620,13620,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عَطَاءٌ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ وَقَالَ ‏ ‏لِي ‏ ‏عَطَاءٌ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَجْمَعُوا بَيْنَ الرُّطَبِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالزَّبِيبِ وَالتَّمْرِ ‏ ‏نَبِيذًا ‏","","",""],[13621,13621,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَقِيلُ بْنُ مَعْقِلٍ ‏ ‏سَمِعْتُ ‏ ‏وَهْبَ بْنَ مُنَبِّهٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏النَّشْرَةِ ‏ ‏فَقَالَ مِنْ عَمَلِ الشَّيْطَانِ ‏","","",""],[13622,13622,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏وَرَأَيْتُ أَنَا ‏ ‏جَابِرًا ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏فِي حَدِيثِهِ وَرَأَيْتُ ‏ ‏جَابِرًا ‏ ‏يُصَلِّي وَلَمْ يُسَمِّ ‏ ‏أَبَا الزُّبَيْرِ ‏","","",""],[13623,13623,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو حُمَيْدٍ الْأَنْصَارِيُّ ‏ ‏بِإِنَاءٍ مِنْ لَبَنٍ نَهَارًا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا ‏ ‏خَمَّرْتَهُ ‏ ‏وَلَوْ أَنْ تَعْرُضَ عَلَيْهِ عُودًا ‏ ‏حَدَّثَنَا ‏ ‏عَقِيلُ بْنُ مَعْقِلٍ هُوَ أَبُو إِبْرَاهِيمَ بْنُ عَقِيلٍ ‏ ‏قَالَ ذَهَبْتُ إِلَى ‏ ‏إِبْرَاهِيمَ بْنِ عَقِيلٍ ‏ ‏وَكَانَ عَسِرًا لَا يُوصَلُ إِلَيْهِ فَأَقَمْتُ عَلَى بَابِهِ ‏ ‏بِالْيَمَنِ ‏ ‏يَوْمًا ‏ ‏أَوْ يَوْمَيْنِ ‏ ‏حَتَّى وَصَلْتُ إِلَيْهِ فَحَدَّثَنِي بِحَدِيثَيْنِ وَكَانَ عِنْدَهُ أَحَادِيثُ ‏ ‏وَهْبٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فَلَمْ أَقْدِرْ أَنْ أَسْمَعَهَا مِنْ عُسْرِهِ وَلَمْ يُحَدِّثْنَا بِهَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْكَرِيمِ ‏ ‏لِأَنَّهُ كَانَ حَيًّا أَفَلَمْ أَسْمَعْهَا مِنْ أَحَدٍ آخَرَ ‏","","",""],[13624,13624,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ‏ ‏جَافَى ‏ ‏حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ ‏","","",""],[13625,13625,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَبُوكَ ‏ ‏عِشْرِينَ يَوْمًا يَقْصُرُ الصَّلَاةَ ‏","","",""],[13626,13626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏لَمَّا بُنِيَتْ ‏ ‏الْكَعْبَةُ ‏ ‏ذَهَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبَّاسٌ ‏ ‏يَنْقُلَانِ حِجَارَةً فَقَالَ ‏ ‏عَبَّاسٌ ‏ ‏اجْعَلْ ‏ ‏إِزَارَكَ ‏ ‏عَلَى رَقَبَتِكَ مِنْ الْحِجَارَةِ فَفَعَلَ ‏ ‏فَخَرَّ ‏ ‏إِلَى الْأَرْضِ ‏ ‏وَطَمَحَتْ ‏ ‏عَيْنَاهُ إِلَى السَّمَاءِ ثُمَّ قَامَ فَقَالَ ‏ ‏إِزَارِي ‏ ‏إِزَارِي ‏ ‏فَشُدَّ عَلَيْهِ ‏ ‏إِزَارُهُ ‏","","",""],[13627,13627,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أُقَاتِلُ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا فَعَلُوا ذَلِكَ ‏ ‏عَصَمُوا ‏ ‏دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ‏","","",""],[13628,13628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَطَبَ يَسْتَنِدُ إِلَى جِذْعِ نَخْلَةٍ مِنْ ‏ ‏سَوَارِي ‏ ‏الْمَسْجِدِ فَلَمَّا صُنِعَ لَهُ مِنْبَرُهُ اسْتَوَى عَلَيْهِ ‏ ‏اضْطَرَبَتْ ‏ ‏تِلْكَ ‏ ‏السَّارِيَةُ ‏ ‏كَحَنِينِ النَّاقَةِ حَتَّى سَمِعَهَا أَهْلُ الْمَسْجِدِ حَتَّى نَزَلَ إِلَيْهَا فَاعْتَنَقَهَا فَسَكَنَتْ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فَسَكَتَتْ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فَاضْطَرَبَتْ تِلْكَ ‏ ‏السَّارِيَةُ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏اضْطَرَبَتْ كَحَنِينِ ‏","","",""],[13629,13629,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏أَخْبَرَنَا ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ أَحَدُكُمْ أَخَاهُ يَوْمَ الْجُمُعَةِ ثُمَّ يُخَالِفُهُ إِلَى مَقْعَدِهِ وَلَكِنْ لِيَقُلْ افْسَحُوا ‏","","",""],[13630,13630,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمُ أَحَدُكُمْ أَخَاهُ يَوْمَ الْجُمُعَةِ وَلَكِنْ لِيَقُلْ افْسَحُوا ‏","","",""],[13631,13631,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ خَطَبَ يَوْمًا فَذَكَرَ رَجُلًا مِنْ أَصْحَابِهِ قُبِضَ فَكُفِّنَ فِي كَفَنٍ غَيْرِ طَائِلٍ ‏ ‏وَقُبِرَ ‏ ‏لَيْلًا ‏ ‏فَزَجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُقْبَرَ ‏ ‏الرَّجُلُ بِاللَّيْلِ حَتَّى يُصَلَّى عَلَيْهِ إِلَّا أَنْ يُضْطَرَّ إِنْسَانٌ إِلَى ذَلِكَ وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَفَّنَ أَحَدُكُمْ أَخَاهُ فَلْيُحْسِنْ كَفَنَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏سُئِلَ ‏ ‏جَابِرٌ ‏ ‏عَنْ الْكَفَنِ ‏ ‏فَأَخْبَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ يَوْمًا فَذَكَرَ رَجُلًا قُبِضَ وَكُفِّنَ فِي كَفَنٍ غَيْرِ ‏ ‏طَائِلٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[13632,13632,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِجَنَازَةٍ مَرَّتْ بِهِ حَتَّى ‏ ‏تَوَارَتْ ‏ ‏قَالَ ‏ ‏فَأَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَيْضًا ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ لِجَنَازَةِ يَهُودِيٍّ حَتَّى ‏ ‏تَوَارَتْ ‏","","",""],[13633,13633,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ يُقْعَدَ عَلَى الْقَبْرِ وَأَنْ ‏ ‏يُقَصَّصَ ‏ ‏أَوْ ‏ ‏يُبْنَى عَلَيْهِ ‏","","",""],[13634,13634,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏قَالَ قَالَ ‏ ‏جَابِرٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ يَقْعُدَ الرَّجُلُ عَلَى الْقَبْرِ وَأَنْ ‏ ‏يُجَصَّصَ ‏ ‏أَوْ ‏ ‏يُبْنَى عَلَيْهِ ‏","","",""],[13635,13635,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏تُوُفِّيَ الْيَوْمَ رَجُلٌ صَالِحٌ مِنْ ‏ ‏الْحَبَشِ ‏ ‏هَلُمَّ فَصُفُّوا قَالَ فَصَفَفْنَا فَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِ وَنَحْنُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏و قَالَ ‏ ‏اسْمُ ‏ ‏النَّجَاشِيِّ ‏ ‏أَصْحَمَةُ ‏","","",""],[13636,13636,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا نَخْلًا ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فَسَمِعَ أَصْوَاتَ رِجَالٍ مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏مَاتُوا فِي الْجَاهِلِيَّةِ يُعَذَّبُونَ فِي قُبُورِهِمْ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَزِعًا ‏ ‏فَأَمَرَ أَصْحَابَهُ أَنْ تَعَوَّذُوا مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[13637,13637,"","","‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏أَيْضًا ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَجَنَازَةُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏مَوْضُوعَةٌ بَيْنَ أَيْدِيهِمْ اهْتَزَّ لَهَا عَرْشُ الرَّحْمَنِ ‏","","",""],[13638,13638,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جُبَيْرٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏مُحَمَّدُ بْنُ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏أَسَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ صِيَامِ يَوْمِ الْجُمُعَةِ قَالَ نَعَمْ وَرَبِّ هَذَا ‏ ‏الْبَيْتِ ‏","","",""],[13639,13639,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏زَجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَصِلَ الْمَرْأَةُ بِرَأْسِهَا شَيْئًا ‏","","",""],[13640,13640,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏النَّوَافِلَ ‏ ‏فِي كُلِّ جِهَةٍ وَلَكِنَّهُ يَخْفِضُ السُّجُودَ مِنْ الرَّكْعَةِ ‏ ‏وَيُومِئُ ‏ ‏إِيمَاءً ‏","","",""],[13641,13641,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّمَا جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشُّفْعَةَ ‏ ‏فِي كُلِّ مَالٍ لَمْ يُقْسَمْ فَإِذَا وَقَعَتْ الْحُدُودُ ‏ ‏وَصُرِّفَتْ ‏ ‏الطُّرُقُ فَلَا ‏ ‏شُفْعَةَ ‏","","",""],[13642,13642,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ ‏} ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ فَأَيُّمَا رَجُلٍ مَاتَ وَتَرَكَ دَيْنًا فَإِلَيَّ وَمَنْ تَرَكَ مَالًا فَهُوَ لِوَرَثَتِهِ ‏","","",""],[13643,13643,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُصَلِّي عَلَى رَجُلٍ عَلَيْهِ دَيْنٌ فَأُتِيَ بِمَيِّتٍ فَسَأَلَ هَلْ عَلَيْهِ دَيْنٌ قَالُوا نَعَمْ دِينَارَانِ قَالَ صَلُّوا عَلَى صَاحِبِكُمْ فَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏هُمَا عَلَيَّ يَا رَسُولَ اللَّهِ فَصَلَّى عَلَيْهِ فَلَمَّا فَتَحَ اللَّهُ عَزَّ وَجَلَّ عَلَى رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ فَمَنْ تَرَكَ دَيْنًا فَعَلَيَّ وَمَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ ‏","","",""],[13644,13644,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحِجْرِ ‏ ‏قَالَ ‏ ‏لَا تَسْأَلُوا الْآيَاتِ وَقَدْ سَأَلَهَا قَوْمُ ‏ ‏صَالِحٍ ‏ ‏فَكَانَتْ تَرِدُ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏وَتَصْدُرُ مِنْ هَذَا ‏ ‏الْفَجِّ ‏ ‏فَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ فَعَقَرُوهَا فَكَانَتْ تَشْرَبُ مَاءَهُمْ يَوْمًا وَيَشْرَبُونَ لَبَنَهَا يَوْمًا فَعَقَرُوهَا فَأَخَذَتْهُمْ صَيْحَةٌ أَهْمَدَ اللَّهُ عَزَّ وَجَلَّ مَنْ تَحْتَ ‏ ‏أَدِيمِ ‏ ‏السَّمَاءِ مِنْهُمْ إِلَّا رَجُلًا وَاحِدًا كَانَ فِي حَرَمِ اللَّهِ عَزَّ وَجَلَّ قِيلَ مَنْ هُوَ يَا رَسُولَ اللَّهِ قَالَ هُوَ ‏ ‏أَبُو رِغَالٍ ‏ ‏فَلَمَّا خَرَجَ مِنْ ‏ ‏الْحَرَمِ ‏ ‏أَصَابَهُ مَا أَصَابَ قَوْمَهُ ‏","","",""],[13645,13645,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏خَرَصَهَا ‏ ‏ابْنُ رَوَاحَةَ ‏ ‏أَرْبَعِينَ أَلْفَ ‏ ‏وَسْقٍ ‏ ‏وَزَعَمَ أَنَّ ‏ ‏الْيَهُودَ ‏ ‏لَمَّا خَيَّرَهُمْ ‏ ‏ابْنُ رَوَاحَةَ ‏ ‏أَخَذُوا الثَّمَرَ وَعَلَيْهِمْ عِشْرُونَ أَلْفَ ‏ ‏وَسْقٍ ‏","","",""],[13646,13646,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏صَدَقَةَ ‏ ‏فِيمَا دُونَ خَمْسِ ‏ ‏أَوَاقٍ ‏ ‏وَلَا فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسُقٍ ‏ ‏وَلَا فِيمَا دُونَ خَمْسَةِ ‏ ‏ذَوْدٍ ‏","","",""],[13647,13647,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ يَوْمَ الْفِطْرِ فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ ثُمَّ خَطَبَ النَّاسَ فَلَمَّا فَرَغَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ فَأَتَى النِّسَاءَ ‏ ‏فَذَكَّرَهُنَّ وَهُوَ يَتَوَكَّأُ عَلَى يَدِ ‏ ‏بِلَالٍ ‏ ‏وَبِلَالٌ ‏ ‏بَاسِطٌ ثَوْبَهُ يُلْقِينَ فِيهِ النِّسَاءُ ‏ ‏صَدَقَةً ‏ ‏قَالَ تُلْقِي الْمَرْأَةُ ‏ ‏فَتْخَهَا ‏ ‏وَيُلْقِينَ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فَتْخَتَهَا ‏","","",""],[13648,13648,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارًا قَدْ ‏ ‏وُسِمَ ‏ ‏فِي وَجْهِهِ فَقَالَ ‏ ‏لَعَنَ اللَّهُ مَنْ فَعَلَ هَذَا ‏","","",""],[13649,13649,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عُبَيْدِ اللَّهِ ‏ ‏أَوْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏أَنَا أَشُكُّ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ الضَّبُعِ فَقَالَ حَلَالٌ فَقُلْتُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[13650,13650,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَيَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ زَيْدٍ الصَّنْعَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا الزُّبَيْرِ الْمَكِّيَّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ثَمَنِ ‏ ‏الْهِرِّ ‏","","",""],[13651,13651,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَقَالَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[13652,13652,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏لَا وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ وَلَمْ يَرْفَعَاهُ ‏","","",""],[13653,13653,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ قَتْلَى ‏ ‏أُحُدٍ ‏ ‏حُمِلُوا مِنْ مَكَانِهِمْ فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ رُدُّوا الْقَتْلَى إِلَى ‏ ‏مَضَاجِعِهَا ‏","","",""],[13654,13654,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَيْنٍ كَانَ عَلَى أَبِي فَأَتَيْتُهُ كَأَنِّي شَرَارَةٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَ لِي ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏اكْتُبْ عَنِّي وَلَوْ حَدِيثًا وَاحِدًا مِنْ غَيْرِ كِتَابٍ فَقُلْتُ لَا وَلَا حَرْفًا ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏سُفْيَانَ بْنَ وَكِيعٍ ‏ ‏قَالَ سَمِعْتُ أَبِي وَذَكَرَ ‏ ‏عَبْدَ الرَّزَّاقِ ‏ ‏فَقَالَ يُشْبِهُ رِجَالَ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُ أَبِي يَقُولُ وَمَا كَانَ فِي قَرْيَةِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏بِئْرٌ فَكُنَّا نَذْهَبُ نُبَكِّرُ عَلَى مِيلَيْنِ نَتَوَضَّأُ وَنَحْمِلُ مَعَنَا الْمَاءَ ‏","","",""],[13655,13655,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ الْإِسْكَافُ ‏ ‏إِنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏سُلَيْكًا ‏ ‏جَاءَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَجَلَسَ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُصَلِّيَ رَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏فِي حَدِيثِهِ ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ إِذَا جَاءَ أَحَدُكُمْ وَالْإِمَامُ يَخْطُبُ فَلْيُصَلِّ رَكْعَتَيْنِ ‏ ‏يَتَجَوَّزُ ‏ ‏فِيهِمَا ‏","","",""],[13656,13656,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ لِأَهْلِهَا ‏ ‏أَوْ مِيرَاثٌ لِأَهْلِهَا ‏","","",""],[13657,13657,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏حَدَّثَ أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نَهَوْا عَنْ الصَّرْفِ وَرَفَعَهُ رَجُلَانِ مِنْهُمْ ‏","","",""],[13658,13658,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ ‏","","",""],[13659,13659,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ ‏","","",""],[13660,13660,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ ‏ ‏غَيْرَ مَرَّةٍ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏تَزَوَّجْتُ ‏ ‏ثَيِّبًا ‏ ‏فَقَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ وَلِلْعَذَارَى وَلِعَابِهَا ‏","","",""],[13661,13661,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَرْبُ خَدْعَةٌ ‏","","",""],[13662,13662,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَرَوْحٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْشِ فِي نَعْلٍ وَاحِدَةٍ وَلَا ‏ ‏تَحْتَبِيَنَّ ‏ ‏فِي ‏ ‏إِزَارٍ ‏ ‏وَاحِدٍ وَلَا تَأْكُلْ بِشِمَالِكَ وَلَا تَشْتَمِلْ ‏ ‏الصَّمَّاءَ ‏ ‏وَلَا تَضَعْ إِحْدَى رِجْلَيْكَ عَلَى الْأُخْرَى ‏ ‏إِذَا اسْتَلْقَيْتَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي الزُّبَيْرِ ‏ ‏أَوَضْعُهُ رِجْلَهُ عَلَى الرُّكْبَةِ مُسْتَلْقِيًا قَالَ نَعَمْ قَالَ أَمَّا ‏ ‏الصَّمَّاءُ ‏ ‏فَهِيَ إِحْدَى اللِّبْسَتَيْنِ تَجْعَلُ دَاخِلَةَ ‏ ‏إِزَارِكَ ‏ ‏وَخَارِجَتَهُ عَلَى إِحْدَى عَاتِقَيْكَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي الزُّبَيْرِ ‏ ‏فَإِنَّهُمْ يَقُولُونَ لَا ‏ ‏يَحْتَبِي ‏ ‏فِي ‏ ‏إِزَارٍ ‏ ‏وَاحِدٍ مُفْضِيًا قَالَ كَذَلِكَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يَحْتَبِي ‏ ‏فِي ‏ ‏إِزَارٍ ‏ ‏وَاحِدٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏لِي ‏ ‏مُفْضِيًا ‏","","",""],[13663,13663,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏ذَكْوَانَ أَبَا صَالِحٍ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ ‏ ‏نَهَوْا عَنْ ‏ ‏الصَّرْفِ ‏ ‏رَفَعَهُ رَجُلَانِ مِنْهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13664,13664,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْفَقِيرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى بِهِمْ صَلَاةَ الْخَوْفِ فَقَامَ صَفٌّ بَيْنَ يَدَيْهِ وَصَفٌّ خَلْفَهُ فَصَلَّى بِالَّذِي خَلْفَهُ رَكْعَةً وَسَجْدَتَيْنِ ثُمَّ تَقَدَّمَ هَؤُلَاءِ حَتَّى قَامُوا فِي مَقَامِ أَصْحَابِهِمْ وَجَاءَ أُولَئِكَ حَتَّى قَامُوا مَقَامَ هَؤُلَاءِ فَصَلَّى بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَةً وَسَجْدَتَيْنِ ثُمَّ سَلَّمَ فَكَانَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ وَلَهُمْ رَكْعَةً ‏","","",""],[13665,13665,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏قَالَ فَقَالَ ‏ ‏لَوْ كُنَّا مِائَةَ أَلْفٍ لَكَفَانَا كُنَّا أَلْفًا وَخَمْسَ مِائَةٍ ‏","","",""],[13666,13666,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏قَالَ ‏ ‏فَذُكِرَ ذَلِكَ ‏ ‏لِجَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏فَقَالَ عَلَى يَدَيَّ دَارَ الْحَدِيثُ ‏ ‏تَمَتَّعْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13667,13667,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وُلِدَ لَهُ غُلَامٌ فَأَرَادَ أَنْ يُسَمِّيَهُ ‏ ‏مُحَمَّدًا ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَقَالَ أَحْسَنَتْ ‏ ‏الْأَنْصَارُ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[13668,13668,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏إِذَا دَخَلْتَ لَيْلًا فَلَا تَدْخُلْ عَلَى أَهْلِكَ حَتَّى ‏ ‏تَسْتَحِدَّ ‏ ‏الْمُغِيبَةُ ‏ ‏وَتَمْتَشِطَ ‏ ‏الشَّعِثَةُ ‏","","",""],[13669,13669,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلْتَ فَعَلَيْكَ ‏ ‏الْكَيْسَ ‏ ‏وَالْكَيْسَ ‏","","",""],[13670,13670,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ ذَا فَقُلْتُ أَنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَنَا ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏كَأَنَّهُ كَرِهَ قَوْلَهُ أَنَا ‏","","",""],[13671,13671,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا وَجِعٌ لَا أَعْقِلُ قَالَ ‏ ‏فَتَوَضَّأَ ثُمَّ صَبَّ عَلَيَّ ‏ ‏أَوْ قَالَ صَبُّوا عَلَيَّ ‏ ‏فَعَقَلْتُ فَقُلْتُ إِنَّهُ لَا يَرِثُنِي إِلَّا ‏ ‏كَلَالَةٌ ‏ ‏فَكَيْفَ الْمِيرَاثُ قَالَ فَنَزَلَتْ ‏ ‏آيَةُ الْفَرْضِ ‏","","",""],[13672,13672,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قُتِلَ أَبِي قَالَ جَعَلْتُ أَكْشِفُ الثَّوْبَ عَنْ وَجْهِهِ قَالَ فَجَعَلَ الْقَوْمُ يَنْهَوْنِي وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْهَانِي قَالَ فَجَعَلَتْ عَمَّتِي ‏ ‏فَاطِمَةُ بِنْتُ عَمْرٍو ‏ ‏تَبْكِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَبْكِينَ أَوْ لَا تَبْكِينَ مَا زَالَتْ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهِمْ حَتَّى رَفَعْتُمُوهُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ تُظَلِّلُهُ ‏","","",""],[13673,13673,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مِخْوَلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُفْرِغُ عَلَى رَأْسِهِ ثَلَاثًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَظُنُّهُ فِي الْغُسْلِ مِنْ ‏ ‏الْجَنَابَةِ ‏ ‏فَقَالَ رَجُلٌ مِنْ ‏ ‏بَنِي هَاشِمٍ ‏ ‏إِنَّ شَعْرِي كَثِيرٌ فَقَالَ ‏ ‏جَابِرٌ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ شَعْرًا مِنْكَ وَأَطْيَبَ ‏","","",""],[13674,13674,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ رَبِّهِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي قَتْلَى ‏ ‏أُحُدٍ ‏ ‏لَا تُغَسِّلُوهُمْ فَإِنَّ كُلَّ جُرْحٍ ‏ ‏أَوْ كُلَّ دَمٍ ‏ ‏يَفُوحُ مِسْكًا يَوْمَ الْقِيَامَةِ وَلَمْ يُصَلِّ عَلَيْهِمْ ‏","","",""],[13675,13675,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏أَقْبَلَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَمَعَهُ ‏ ‏نَاضِحَانِ ‏ ‏لَهُ وَقَدْ جَنَحَتْ الشَّمْسُ ‏ ‏وَمُعَاذٌ ‏ ‏يُصَلِّي الْمَغْرِبَ فَدَخَلَ مَعَهُ الصَّلَاةَ فَاسْتَفْتَحَ ‏ ‏مُعَاذٌ ‏ ‏الْبَقَرَةَ ‏ ‏أَوْ ‏ ‏النِّسَاءَ ‏ ‏مُحَارِبٌ ‏ ‏الَّذِي يَشُكُّ ‏ ‏فَلَمَّا رَأَى الرَّجُلُ ذَلِكَ صَلَّى ثُمَّ خَرَجَ قَالَ فَبَلَغَهُ أَنَّ ‏ ‏مُعَاذًا ‏ ‏نَالَ مِنْهُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَنَالُ مِنْهُ ‏ ‏قَالَ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ يَا ‏ ‏مُعَاذُ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ يَا ‏ ‏مُعَاذُ ‏ ‏أَوْ فَاتِنٌ فَاتِنٌ فَاتِنٌ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏أَفَاتِنٌ أَفَاتِنٌ أَفَاتِنٌ ‏ ‏فَلَوْلَا قَرَأْتَ ‏ ‏سَبِّحْ اسْمَ رَبِّكَ ‏ ‏الْأَعْلَى ‏ ‏وَالشَّمْسِ وَضُحَاهَا ‏ ‏فَصَلَّى وَرَاءَكَ الْكَبِيرُ وَذُو الْحَاجَةِ وَالضَّعِيفُ ‏ ‏أَحْسِبُ ‏ ‏مُحَارِبًا ‏ ‏الَّذِي يَشُكُّ فِي الضَّعِيفِ ‏","","",""],[13676,13676,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏ح ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏أَخْبَرَنِي أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ أَنْ يَأْتِيَ أَهْلَهُ ‏ ‏طُرُوقًا ‏ ‏أَوْ قَالَ كَانَ يَكْرَهُ أَنْ يَأْتِيَ الرَّجُلُ أَهْلَهُ ‏ ‏طُرُوقًا ‏","","",""],[13677,13677,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا لِي فِي سَفَرٍ فَلَمَّا أَتَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتِ الْمَسْجِدَ فَصَلِّ رَكْعَتَيْنِ ثُمَّ وَزَنَ لِي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ أَمَرَ فَوُزِنَ لِي ‏ ‏فَأَرْجَحَ لِي فَمَا زَالَ عِنْدِي مِنْهَا شَيْءٌ حَتَّى أَصَابَهَا أَهْلُ ‏ ‏الشَّامِ ‏ ‏يَوْمَ ‏ ‏الْحَرَّةِ ‏","","",""],[13678,13678,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ سَعْدِ بْنِ زُرَارَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ يَعْنِي هَاشِمًا ‏ ‏فِي سَفَرٍ ‏ ‏قَالَ ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَرَأَى رَجُلًا قَدْ اجْتَمَعَ النَّاسُ عَلَيْهِ وَقَدْ ظُلِّلَ عَلَيْهِ قَالُوا هَذَا رَجُلٌ صَائِمٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْبِرُّ أَنْ تَصُومُوا فِي السَّفَرِ ‏","","",""],[13679,13679,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ الْعَنَزِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلْتُمْ لَيْلًا فَلَا يَأْتِيَنَّ أَحَدُكُمْ أَهْلَهُ ‏ ‏طُرُوقًا ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏فَوَاللَّهِ لَقَدْ طَرَقْنَاهُنَّ بَعْدُ ‏","","",""],[13680,13680,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسِيرُ عَلَى جَمَلٍ لِي فَأَعْيَا فَأَرَدْتُ أَنْ أُسَيِّبَهُ قَالَ فَلَحِقَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَرَبَهُ بِرِجْلِهِ وَدَعَا لَهُ فَسَارَ سَيْرًا لَمْ يَسِرْ مِثْلَهُ وَقَالَ بِعْنِيهِ بِوُقِيَّةٍ فَكَرِهْتُ أَنْ أَبِيعَهُ قَالَ بِعْنِيهِ فَبِعْتُهُ مِنْهُ وَاشْتَرَطْتُ حُمْلَانَهُ إِلَى أَهْلِي فَلَمَّا قَدِمْنَا أَتَيْتُهُ بِالْجَمَلِ فَقَالَ ظَنَنْتَ حِينَ مَاكَسْتُكَ أَنْ أَذْهَبَ بِجَمَلِكَ خُذْ جَمَلَكَ وَثَمَنَهُ هُمَا لَكَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَسِيرُ عَلَى جَمَلٍ وَذَكَرَ مَعْنَاهُ وَقَالَ فَاسْتَثْنَيْتُ حُمْلَانَهُ إِلَى أَهْلِي ‏","","",""],[13681,13681,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ ‏ ‏ح ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ قَيْسٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَعْطَى أُمَّهُ حَدِيقَةً مِنْ نَخْلٍ حَيَاتَهَا فَمَاتَتْ فَجَاءَ إِخْوَتُهُ فَقَالُوا نَحْنُ فِيهِ شَرْعٌ سَوَاءٌ فَأَبَى ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَسَمَهَا بَيْنَهُمْ مِيرَاثًا ‏","","",""],[13682,13682,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْأَخْنَسِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ ‏ ‏أَوْ اسْتَلْقَى ‏ ‏أَحَدُكُمْ فَلَا يَضَعْ رِجْلَيْهِ إِحْدَاهُمَا عَلَى الْأُخْرَى ‏","","",""],[13683,13683,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ الرُّطَبِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ وَالزَّبِيبِ ‏","","",""],[13684,13684,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏نَحْوَ الْمَشْرِقِ فِي غَزْوَةِ ‏ ‏أَنْمَارٍ ‏","","",""],[13685,13685,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُتَعَاطَى السَّيْفُ ‏ ‏مَسْلُولًا ‏","","",""],[13686,13686,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏مُعَاذًا ‏ ‏صَلَّى بِأَصْحَابِهِ فَقَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏فِي الْفَجْرِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏الْمَغْرِبَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَتَّانًا ‏ ‏أَفَتَّانًا ‏","","",""],[13687,13687,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏","","",""],[13688,13688,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مَسْحِ الْحَصَى فَقَالَ وَاحِدَةٌ وَلَئِنْ تُمْسِكْ عَنْهَا خَيْرٌ لَكَ مِنْ مِائَةِ ‏ ‏بَدَنَةٍ ‏ ‏كُلُّهَا سُودُ ‏ ‏الْحَدَقَةِ ‏","","",""],[13689,13689,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏صُرِعَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فَرَسٍ عَلَى جِذْعِ نَخْلَةٍ فَانْفَكَّتْ قَدَمُهُ فَدَخَلْنَا عَلَيْهِ ‏ ‏نَعُودُهُ ‏ ‏فَوَجَدْنَاهُ ‏ ‏يُصَلِّي فَصَلَّيْنَا بِصَلَاتِهِ وَنَحْنُ قِيَامٌ فَلَمَّا صَلَّى قَالَ إِنَّمَا ‏ ‏جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا وَلَا تَقُومُوا وَهُوَ جَالِسٌ كَمَا يَفْعَلُ أَهْلُ ‏ ‏فَارِسٍ ‏ ‏بِعُظَمَائِهَا ‏","","",""],[13690,13690,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ إِلَى جِذْعِ نَخْلَةٍ قَالَ فَقَالَتْ امْرَأَةٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَ لَهَا غُلَامٌ نَجَّارٌ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي غُلَامًا نَجَّارًا أَفَآمُرُهُ أَنْ يَتَّخِذَ لَكَ مِنْبَرًا تَخْطُبُ عَلَيْهِ قَالَ بَلَى قَالَ فَاتَّخَذَ لَهُ مِنْبَرًا قَالَ فَلَمَّا كَانَ يَوْمُ الْجُمُعَةِ خَطَبَ عَلَى الْمِنْبَرِ قَالَ فَأَنَّ الْجِذْعُ الَّذِي كَانَ يَقُومُ عَلَيْهِ كَمَا يَئِنُّ الصَّبِيُّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذَا بَكَى لِمَا فَقَدَ مِنْ الذِّكْرِ ‏","","",""],[13691,13691,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ظَنَّ مِنْكُمْ أَنْ لَا يَسْتَيْقِظَ آخِرَهُ ‏ ‏فَلْيُوتِرْ ‏ ‏أَوَّلَهُ وَمَنْ ظَنَّ مِنْكُمْ أَنَّهُ يَسْتَيْقِظُ آخِرَهُ ‏ ‏فَلْيُوتِرْ ‏ ‏آخِرَهُ فَإِنَّ صَلَاةَ آخِرِ اللَّيْلِ ‏ ‏مَحْضُورَةٌ ‏ ‏وَهِيَ أَفْضَلُ ‏","","",""],[13692,13692,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏خَلَّفْتُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏رِجَالًا مَا قَطَعْتُمْ وَادِيًا وَلَا سَلَكْتُمْ طَرِيقًا إِلَّا شَرَكُوكُمْ فِي الْأَجْرِ حَبَسَهُمْ الْمَرَضُ ‏","","",""],[13693,13693,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَه إِلَّا اللَّهُ فَإِذَا قَالُوهَا عَصَمُوا مِنِّي بِهَا دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ثُمَّ قَرَأَ ‏ { ‏فَذَكِّرْ إِنَّمَا أَنْتَ مُذَّكِرٌ لَسْتَ عَلَيْهِمْ ‏ ‏بِمُصَيْطِرٍ ‏}","","",""],[13694,13694,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ ‏ ‏وَأُهْرِيقَ ‏ ‏دَمُهُ ‏","","",""],[13695,13695,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏مَكَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ ‏ ‏وَهُمْ يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏ثَلَاثًا لَمْ يَذُوقُوا طَعَامًا فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّ هَاهُنَا ‏ ‏كُدْيَةً ‏ ‏مِنْ الْجَبَلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُشُّوهَا بِالْمَاءِ فَرَشُّوهَا ثُمَّ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ ‏ ‏الْمِعْوَلَ ‏ ‏أَوْ ‏ ‏الْمِسْحَاةَ ‏ ‏ثُمَّ قَالَ بِسْمِ اللَّهِ فَضَرَبَ ثَلَاثًا فَصَارَتْ ‏ ‏كَثِيبًا ‏ ‏يُهَالُ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَحَانَتْ مِنِّي الْتِفَاتَةٌ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ شَدَّ عَلَى بَطْنِهِ حَجَرًا ‏","","",""],[13696,13696,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ تَزَوَّجَ بِغَيْرِ إِذْنِ ‏ ‏مَوَالِيهِ ‏ ‏أَوْ أَهْلِهِ ‏ ‏فَهُوَ ‏ ‏عَاهِرٌ ‏","","",""],[13697,13697,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏نَحَرُوا ‏ ‏جَزُورًا ‏ ‏أَوْ بَقَرَةً ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏نَحَرْتُ ‏ ‏جَزُورًا ‏ ‏أَوْ بَقَرَةً ‏","","",""],[13698,13698,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَاعَ عَبْدًا وَلَهُ مَالٌ فَمَالُهُ لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[13699,13699,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاعَ ‏ ‏الْمُدَبَّرَ ‏","","",""],[13700,13700,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاعَ ‏ ‏الْمُدَبَّرَ ‏","","",""],[13701,13701,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاعَ ‏ ‏الْمُدَبَّرَ ‏","","",""],[13702,13702,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْضَعَ فِي ‏ ‏وَادِي مُحَسِّرٍ ‏","","",""],[13703,13703,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِتَأْخُذْ أُمَّتِي مَنَاسِكَهَا وَارْمُوا بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏","","",""],[13704,13704,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَمَّا حَفَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ ‏ ‏الْخَنْدَقَ ‏ ‏أَصَابَهُمْ جَهْدٌ شَدِيدٌ حَتَّى رَبَطَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَطْنِهِ حَجَرًا مِنْ الْجُوعِ ‏","","",""],[13705,13705,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلَا يَمْسَحْ يَدَهُ فِي الْمِنْدِيلِ حَتَّى يَلْعَقَهَا ‏ ‏أَوْ يُلْعِقَهَا ‏ ‏فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ الْبَرَكَةُ ‏","","",""],[13706,13706,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامُ الْوَاحِدِ يَكْفِي ‏ ‏الِاثْنَيْنِ وَطَعَامُ ‏ ‏الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ وَطَعَامُ الْأَرْبَعَةِ يَكْفِي الثَّمَانِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏مِثْلَهُ ‏","","",""],[13707,13707,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏مَا بِهَا مِنْ الْأَذَى وَلْيَأْكُلْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ ‏","","",""],[13708,13708,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْمُثَنَّى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ طَلْحَةَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ ‏ ‏الْأُدْمُ ‏ ‏الْخَلُّ ‏","","",""],[13709,13709,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَمَّا تَزَوَّجْتُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ اتَّخَذْتُمْ ‏ ‏أَنْمَاطًا ‏ ‏قَالَ قُلْتُ أَنَّى لَنَا ‏ ‏أَنْمَاطٌ ‏ ‏قَالَ أَمَا إِنَّهَا سَتَكُونُ وَأَنَا أَقُولُ لِامْرَأَتِي نَحِّي عَنِّي ‏ ‏نَمَطَكِ ‏ ‏فَتَقُولُ أَوَلَيْسَ قَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَكُونُ ‏","","",""],[13710,13710,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي فَإِنِّي أَنَا ‏ ‏أَبُو الْقَاسِمِ ‏ ‏أَقْسِمُ بَيْنَكُمْ ‏","","",""],[13711,13711,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏فِطْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَغْلِقُوا أَبْوَابَكُمْ ‏ ‏وَخَمِّرُوا ‏ ‏آنِيَتَكُمْ وَأَطْفِئُوا ‏ ‏سُرُجَكُمْ ‏ ‏وَأَوْكُوا ‏ ‏أَسْقِيَتَكُمْ ‏ ‏فَإِنَّ ‏ ‏الشَّيْطَانَ لَا يَفْتَحُ بَابًا مُغْلَقًا وَلَا يَكْشِفُ غِطَاءً وَلَا يَحُلُّ ‏ ‏وِكَاءً ‏ ‏وَإِنَّ الْفُوَيْسِقَةَ ‏ ‏تُضْرِمُ ‏ ‏الْبَيْتَ عَلَى أَهْلِهِ ‏ ‏يَعْنِي الْفَأْرَةَ ‏","","",""],[13712,13712,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏حَجَجْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَحَرْنَا الْبَعِيرَ عَنْ سَبْعَةٍ وَالْبَقَرَةَ عَنْ سَبْعَةٍ ‏","","",""],[13713,13713,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُعْمِرُوهَا فَمَنْ أُعْمِرَ عُمْرَى فَهِيَ سَبِيلُ الْمِيرَاثِ ‏","","",""],[13714,13714,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ خَالِي ‏ ‏يَرْقِي ‏ ‏مِنْ الْعَقْرَبِ فَلَمَّا نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الرُّقَى ‏ ‏أَتَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّكَ نَهَيْتَ عَنْ الرُّقَى وَإِنِّي ‏ ‏أَرْقِي ‏ ‏مِنْ الْعَقْرَبِ فَقَالَ ‏ ‏مَنْ اسْتَطَاعَ أَنْ يَنْفَعَ أَخَاهُ فَلْيَفْعَلْ ‏","","",""],[13715,13715,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَطْرُقَ الرَّجُلُ أَهْلَهُ لَيْلًا أَنْ يُخَوِّنَهُمْ أَوْ يَلْتَمِسَ ‏ ‏عَثَرَاتِهِمْ ‏","","",""],[13716,13716,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْجِهَادِ أَفْضَلُ قَالَ مَنْ ‏ ‏عُقِرَ ‏ ‏جَوَادُهُ ‏ ‏وَأُهْرِيقَ ‏ ‏دَمُهُ قَالَ وَسُئِلَ أَيُّ الصَّلَاةِ أَفْضَلُ قَالَ طُولُ ‏ ‏الْقُنُوتِ ‏","","",""],[13717,13717,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏اشْتَرَى مِنِّي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا فَوَزَنَ لِي ثَمَنَهُ وَأَرْجَحَ لِي قَالَ فَقَالَ لِي ‏ ‏هَلْ صَلَّيْتَ صَلِّ رَكْعَتَيْنِ ‏","","",""],[13718,13718,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ لِي عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَيْنٌ ‏ ‏فَقَضَانِي وَزَادَنِي ‏","","",""],[13719,13719,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشُونَ أَمَامَهُ إِذَا خَرَجَ وَيَدَعُونَ ظَهْرَهُ لِلْمَلَائِكَةِ ‏","","",""],[13720,13720,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏ح ‏ ‏وَإِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجْتُ امْرَأَةً عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏جَابِرُ ‏ ‏أَتَزَوَّجْتَ قَالَ قُلْتُ نَعَمْ قَالَ ‏ ‏بِكْرًا ‏ ‏أَوْ ‏ ‏ثَيِّبًا ‏ ‏قَالَ قُلْتُ ‏ ‏ثَيِّبًا ‏ ‏قَالَ أَلَا ‏ ‏بِكْرًا ‏ ‏تُلَاعِبُهَا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ كُنَّ لِي أَخَوَاتٌ فَخَشِيتُ أَنْ تَدْخُلَ بَيْنِي وَبَيْنَهُنَّ فَقَالَ ‏ ‏إِنَّ الْمَرْأَةَ تُنْكَحُ لَدِينِهَا وَمَالِهَا وَجَمَالِهَا فَعَلَيْكَ بِذَاتِ الدِّينِ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكَ ‏","","",""],[13721,13721,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ وَنَحْنُ مُحْرِمُونَ بِالْحَجِّ فَأَمَرَنَا أَنْ نَجْعَلَهَا عُمْرَةً فَضَاقَتْ بِذَلِكَ صُدُورُنَا وَكَبُرَ عَلَيْنَا فَبَلَغَهُ ذَلِكَ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏أَحِلُّوا فَلَوْلَا ‏ ‏الْهَدْيُ ‏ ‏الَّذِي مَعِي لَفَعَلْتُ مِثْلَ مَا تَفْعَلُونَ فَفَعَلْنَا حَتَّى ‏ ‏وَطِئْنَا ‏ ‏النِّسَاءَ مَا يَفْعَلُ الْحَلَالُ حَتَّى إِذَا كَانَ عَشِيَّةُ ‏ ‏التَّرْوِيَةِ ‏ ‏أَوْ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏جَعَلْنَا ‏ ‏مَكَّةَ ‏ ‏بِظَهْرٍ وَلَبَّيْنَا بِالْحَجِّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحْرِمِينَ بِالْحَجِّ فَذَكَرَ مِثْلَهُ وَقَالَ فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏وَجَعَلْنَا ‏ ‏مَكَّةَ ‏ ‏بِظَهْرٍ لَبَّيْنَا بِالْحَجِّ ‏","","",""],[13722,13722,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَابِرٌ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ التَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالزَّبِيبِ وَالتَّمْرِ أَنْ ‏ ‏يُنْبَذَا ‏","","",""],[13723,13723,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ مِقْسَمٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ثُمَّ يَأْتِي قَوْمَهُ فَيُصَلِّي بِهِمْ تِلْكَ الصَّلَاةَ ‏","","",""],[13724,13724,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا فَإِنْ لَمْ يَسْتَطِعْ أَوْ عَجَزَ عَنْهَا فَلْيَمْنَحْهَا أَخَاهُ وَلَا يُؤَاجِرْهَا ‏","","",""],[13725,13725,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى لِمَنْ وُهِبَتْ لَهُ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏نَحْوَهُ ‏","","",""],[13726,13726,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْأَوْعِيَةِ فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏فَلَا بُدَّ لَنَا قَالَ فَلَا إِذًا ‏","","",""],[13727,13727,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْتَعِينُهُ فِي دَيْنٍ كَانَ عَلَى أَبِي قَالَ فَقَالَ آتِيكُمْ قَالَ فَرَجَعْتُ فَقُلْتُ لِلْمَرْأَةِ لَا تُكَلِّمِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا تَسْأَلِيهِ قَالَ فَأَتَانَا فَذَبَحْنَا لَهُ ‏ ‏دَاجِنًا ‏ ‏كَانَ لَنَا فَقَالَ يَا ‏ ‏جَابِرُ ‏ ‏كَأَنَّكُمْ عَرَفْتُمْ حُبَّنَا اللَّحْمَ قَالَ فَلَمَّا خَرَجَ قَالَتْ لَهُ الْمَرْأَةُ صَلِّ عَلَيَّ وَعَلَى زَوْجِي ‏ ‏أَوْ صَلِّ عَلَيْنَا ‏ ‏قَالَ فَقَالَ ‏ ‏اللَّهُمَّ صَلِّ عَلَيْهِمْ ‏ ‏قَالَ ‏ ‏فَقُلْتُ لَهَا أَلَيْسَ قَدْ نَهَيْتُكِ قَالَتْ ‏ ‏تَرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْخُلُ عَلَيْنَا وَلَا يَدْعُو لَنَا ‏","","",""],[13728,13728,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏الظُّهْرُ كَاسْمِهَا وَالْعَصْرُ بَيْضَاءُ حَيَّةٌ وَالْمَغْرِبُ كَاسْمِهَا وَكُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ نَأْتِي مَنَازِلَنَا وَهِيَ عَلَى قَدْرِ مِيلٍ ‏ ‏فَنَرَى مَوَاقِعَ النَّبْلِ وَكَانَ يُعَجِّلُ الْعِشَاءَ وَيُؤَخِّرُ وَالْفَجْرُ كَاسْمِهَا وَكَانَ ‏ ‏يُغَلِّسُ ‏ ‏بِهَا ‏","","",""],[13729,13729,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جَابِرٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كُنَّ لَهُ ثَلَاثُ بَنَاتٍ ‏ ‏يُؤْوِيهِنَّ وَيَرْحَمُهُنَّ وَيَكْفُلُهُنَّ وَجَبَتْ لَهُ الْجَنَّةُ ‏ ‏الْبَتَّةَ ‏ ‏قَالَ قِيلَ يَا رَسُولَ اللَّهِ فَإِنْ كَانَتْ اثْنَتَيْنِ قَالَ وَإِنْ كَانَتْ اثْنَتَيْنِ قَالَ فَرَأَى بَعْضُ الْقَوْمِ أَنْ لَوْ قَالُوا لَهُ وَاحِدَةً لَقَالَ وَاحِدَةً ‏","","",""],[13730,13730,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَلَمَّا رَجَعْنَا ذَهَبْنَا لِنَدْخُلَ فَقَالَ ‏ ‏أَمْهِلُوا حَتَّى نَدْخُلَ لَيْلًا ‏ ‏أَيْ عِشَاءً ‏ ‏لِكَيْ تَمْتَشِطَ ‏ ‏الشَّعِثَةُ ‏ ‏وَتَسْتَحِدَّ ‏ ‏الْمُغِيبَةُ ‏","","",""],[13731,13731,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وُلِدَ لِرَجُلٍ مِنَّا غُلَامٌ فَسَمَّاهُ ‏ ‏الْقَاسِمَ ‏ ‏فَقُلْنَا لَا ‏ ‏نُكَنِّيكَ بِهِ حَتَّى نَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْنَا لَهُ فَقَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي فَإِنَّمَا بُعِثْتُ قَاسِمًا بَيْنَكُمْ ‏","","",""],[13732,13732,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏","","",""],[13733,13733,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏أَبِي هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَاشْتَرَى مِنِّي بَعِيرًا فَجَعَلَ لِي ظَهْرَهُ حَتَّى أَقْدَمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَمَّا قَدِمْتُ أَتَيْتُهُ بِالْبَعِيرِ فَدَفَعْتُهُ إِلَيْهِ ‏ ‏وَأَمَرَ لِي بِالثَّمَنِ ثُمَّ انْصَرَفْتُ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ لَحِقَنِي قَالَ قُلْتُ قَدْ بَدَا لَهُ قَالَ فَلَمَّا أَتَيْتُهُ دَفَعَ إِلَيَّ الْبَعِيرَ وَقَالَ هُوَ لَكَ فَمَرَرْتُ بِرَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَأَخْبَرْتُهُ قَالَ فَجَعَلَ يَعْجَبُ قَالَ فَقَالَ اشْتَرَى مِنْكَ الْبَعِيرَ وَدَفَعَ إِلَيْكَ الثَّمَنَ وَوَهَبَهُ لَكَ قَالَ قُلْتُ نَعَمْ ‏","","",""],[13734,13734,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رُمِيَ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏بِسَهْمٍ فَأَصَابَ ‏ ‏أَكْحَلَهُ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُوِيَ عَلَى ‏ ‏أَكْحَلِهِ ‏","","",""],[13735,13735,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَارُ أَحَقُّ بِشُفْعَةِ جَارِهِ يَنْتَظِرُ بِهَا وَإِنْ كَانَ غَائِبًا إِذَا كَانَ طَرِيقُهُمَا وَاحِدًا ‏","","",""],[13736,13736,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى جَائِزَةٌ لِأَهْلِهَا ‏ ‏وَالرُّقْبَى ‏ ‏جَائِزَةٌ لِأَهْلِهَا ‏","","",""],[13737,13737,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13738,13738,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏بَعَثَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ فِي سَفَرٍ فَنَفِدَ زَادُنَا فَمَرَرْنَا بِحُوتٍ قَذَفَهُ الْبَحْرُ فَأَرَدْنَا أَنْ نَأْكُلَ مِنْهُ فَمَنَعَنَا ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ثُمَّ إِنَّهُ قَالَ ‏ ‏بَعْدَ ذَلِكَ نَحْنُ رُسُلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي سَبِيلِ اللَّهِ كُلُوا قَالَ فَأَكَلْنَا مِنْهُ أَيَّامًا فَلَمَّا قَدِمْنَا ذَكَرْنَا ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنْ كَانَ بَقِيَ مَعَكُمْ مِنْهُ شَيْءٌ فَابْعَثُوا بِهِ إِلَيْنَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَكَوَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ ‏","","",""],[13739,13739,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏سُرَاقَةَ بْنَ مَالِكٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ ‏ ‏فِيمَ الْعَمَلُ أَفِي شَيْءٍ قَدْ فُرِغَ مِنْهُ أَوْ فِي شَيْءٍ نَسْتَأْنِفُهُ فَقَالَ بَلْ فِي شَيْءٍ قَدْ فُرِغَ مِنْهُ قَالَ فَفِيمَ الْعَمَلُ إِذًا قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ‏","","",""],[13740,13740,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَنَا فَأُفْرِغُ عَلَى رَأْسِي ثَلَاثًا ‏","","",""],[13741,13741,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا لَمْ يَزَلْ يَخُوضُ فِي الرَّحْمَةِ حَتَّى ‏ ‏يَجْلِسَ ‏ ‏فَإِذَا جَلَسَ اغْتَمَسَ فِيهَا ‏","","",""],[13742,13742,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ ‏ ‏الْإِدَامُ ‏ ‏الْخَلُّ ‏","","",""],[13743,13743,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَكَلْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏خُبْزًا وَلَحْمًا ‏ ‏فَصَلَّوْا وَلَمْ يَتَوَضَّئُوا ‏","","",""],[13744,13744,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏","","",""],[13745,13745,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ الْفَقِيرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي بُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَدِ وَكَانَ النَّبِيُّ إِنَّمَا يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً وَبُعِثْتُ إِلَى النَّاسِ عَامَّةً وَأُحِلَّتْ لِي الْغَنَائِمُ وَلَمْ تُحَلَّ لِأَحَدٍ قَبْلِي وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏مِنْ مَسِيرَةِ شَهْرٍ وَجُعِلَتْ لِي الْأَرْضُ طَهُورًا وَمَسْجِدًا فَأَيُّمَا رَجُلٍ أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ حَيْثُ أَدْرَكَتْهُ ‏","","",""],[13746,13746,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَتَمَتَّعُ فِي ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَذْبَحُ الْبَقَرَةَ عَنْ سَبْعَةٍ نَشْتَرِكُ فِيهَا ‏","","",""],[13747,13747,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى كُلِّ مُسْلِمٍ غُسْلٌ فِي سَبْعَةِ أَيَّامٍ كُلَّ جُمُعَةٍ ‏","","",""],[13748,13748,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنْتَبَذُ ‏ ‏لَهُ فِي ‏ ‏سِقَاءٍ ‏ ‏فَإِذَا لَمْ يَكُنْ لَهُ ‏ ‏سِقَاءٌ ‏ ‏نُبِذَ ‏ ‏لَهُ فِي ‏ ‏تَوْرٍ ‏ ‏مِنْ ‏ ‏بِرَامٍ ‏","","",""],[13749,13749,"","","‏ ‏قَالَ ‏ ‏وَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْجَرِّ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[13750,13750,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَتَمَتَّعُ ‏ ‏عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏حَتَّى نَهَانَا ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَخِيرًا ‏ ‏يَعْنِي النِّسَاءَ ‏","","",""],[13751,13751,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ فَلْيَزْرَعْهَا فَإِنْ لَمْ يَسْتَطِعْ أَنْ يَزْرَعَهَا أَوْ عَجَزَ عَنْهَا فَلْيَمْنَحْهَا أَخَاهُ الْمُسْلِمَ وَلَا يُؤَاجِرْهَا ‏","","",""],[13752,13752,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى لِمَنْ وُهِبَتْ لَهُ ‏","","",""],[13753,13753,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ الْمُهَلَّبِيُّ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحْيَا أَرْضًا مَيْتَةً فَلَهُ مِنْهَا ‏ ‏يَعْنِي أَجْرًا وَمَا أَكَلَتْ ‏ ‏الْعَوَافِي ‏ ‏مِنْهَا فَهُوَ لَهُ ‏ ‏صَدَقَةٌ ‏","","",""],[13754,13754,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ نَحْوَ الْمَشْرِقِ فَإِذَا أَرَادَ أَنْ يُصَلِّيَ الْمَكْتُوبَةَ نَزَلَ فَاسْتَقْبَلَ الْقِبْلَةَ ‏","","",""],[13755,13755,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو مَذْكُورٍ ‏ ‏أَعْتَقَ غُلَامًا لَهُ يُقَالُ لَهُ ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏دُبُرٍ ‏ ‏لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُ فَدَعَا بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ يَشْتَرِيهِ مَنْ يَشْتَرِيهِ فَاشْتَرَاهُ ‏ ‏نُعَيْمُ بْنُ عَبْدِ اللَّهِ النَّحَّامُ ‏ ‏بِثَمَانِ مِائَةِ دِرْهَمٍ فَدَفَعَهَا إِلَيْهِ وَقَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فَقِيرًا فَلْيَبْدَأْ بِنَفْسِهِ وَإِنْ كَانَ فَضْلًا فَعَلَى عِيَالِهِ وَإِنْ كَانَ فَضْلًا فَعَلَى ذَوِي قَرَابَتِهِ ‏ ‏أَوْ قَالَ عَلَى ذَوِي رَحِمِهِ ‏ ‏وَإِنْ كَانَ فَضْلًا فَهَاهُنَا وَهَاهُنَا ‏","","",""],[13756,13756,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَجْلَحُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏عِنْدَ غُرُوبِ الشَّمْسِ ‏ ‏فَلَمْ يُصَلِّ حَتَّى أَتَى ‏ ‏سَرِفَ ‏ ‏وَهِيَ تِسْعَةُ أَمْيَالٍ مِنْ ‏ ‏مَكَّةَ ‏","","",""],[13757,13757,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الصَّلَوَاتِ الْخَمْسِ الْمَكْتُوبَاتِ كَمَثَلِ نَهَرٍ جَارٍ بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ ‏","","",""],[13758,13758,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلَا يَفْتَرِشْ ذِرَاعَيْهِ افْتِرَاشَ الْكَلْبِ ‏","","",""],[13759,13759,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سِرْتُمْ فِي الْخِصْبِ فَأَمْكِنُوا الرِّكَابَ ‏ ‏أَسْنَانَهَا ‏ ‏وَلَا تُجَاوِزُوا الْمَنَازِلَ وَإِذَا سِرْتُمْ فِي ‏ ‏الْجَدْبِ ‏ ‏فَاسْتَجِدُّوا ‏ ‏وَعَلَيْكُمْ ‏ ‏بِالدَّلْجِ ‏ ‏فَإِنَّ الْأَرْضَ تُطْوَى بِاللَّيْلِ وَإِذَا تَغَوَّلَتْ لَكُمْ الْغِيلَانُ فَنَادُوا بِالْأَذَانِ وَإِيَّاكُمْ وَالصَّلَاةَ عَلَى ‏ ‏جَوَادِّ الطَّرِيقِ ‏ ‏وَالنُّزُولَ عَلَيْهَا فَإِنَّهَا مَأْوَى الْحَيَّاتِ وَالسِّبَاعِ وَقَضَاءِ الْحَاجَةِ فَإِنَّهَا الْمَلَاعِنُ ‏","","",""],[13760,13760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ ‏ ‏قَالَ ‏ ‏جَعْفَرٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَضَى بِهِ ‏ ‏عَلِيٌّ ‏ ‏بِالْعِرَاقِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏كَانَ أَبِي قَدْ ضَرَبَ عَلَى هَذَا الْحَدِيثِ قَالَ وَلَمْ يُوَافِقْ أَحَدٌ ‏ ‏الثَّقَفِيَّ ‏ ‏عَلَى ‏ ‏جَابِرٍ ‏ ‏فَلَمْ أَزَلْ بِهِ حَتَّى قَرَأَهُ عَلَيَّ وَكَتَبَ عَلَيْهِ هُوَ صَحَّ ‏","","",""],[13761,13761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهَلَّ ‏ ‏وَأَصْحَابُهُ بِالْحَجِّ وَلَيْسَ مَعَ أَحَدٍ مِنْهُمْ يَوْمَئِذٍ ‏ ‏هَدْيٌ ‏ ‏إِلَّا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَطَلْحَةَ ‏ ‏وَكَانَ ‏ ‏عَلِيٌّ ‏ ‏قَدِمَ مِنْ ‏ ‏الْيَمَنِ ‏ ‏وَمَعَهُ ‏ ‏الْهَدْيُ ‏ ‏فَقَالَ ‏ ‏أَهْلَلْتُ ‏ ‏بِمَا ‏ ‏أَهَلَّ ‏ ‏بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَصْحَابَهُ أَنْ يَجْعَلُوهَا عُمْرَةً وَيَطُوفُوا ثُمَّ يُقَصِّرُوا وَيَحِلُّوا إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏فَقَالُوا نَنْطَلِقُ إِلَى ‏ ‏مِنًى ‏ ‏وَذَكَرُ أَحَدِنَا يَقْطُرُ فَبَلَغَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ أَنِّي أَسْتَقْبِلُ مِنْ أَمْرِي مَا اسْتُدْبِرَ مَا أَهْدَيْتُ وَلَوْلَا أَنَّ مَعِي ‏ ‏الْهَدْيَ ‏ ‏لَأَحْلَلْتُ وَأَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَاضَتْ فَنَسَكَتْ الْمَنَاسِكَ كُلَّهَا غَيْرَ أَنَّهَا لَمْ تَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏فَلَمَّا طَهُرَتْ طَافَتْ قَالَتْ يَا رَسُولَ اللَّهِ أَتَنْطَلِقُونَ بِحَجٍّ وَعُمْرَةٍ وَأَنْطَلِقُ بِالْحَجِّ فَأَمَرَ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏أَنْ يَخْرُجَ مَعَهَا إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَاعْتَمَرَتْ بَعْدَ الْحَجِّ فِي ذِي الْحِجَّةِ وَأَنَّ ‏ ‏سُرَاقَةَ بْنَ مَالِكِ بْنِ جُعْشُمٍ ‏ ‏لَقِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعَقَبَةِ ‏ ‏وَهُوَ يَرْمِيهَا فَقَالَ أَلَكُمْ هَذِهِ خَاصَّةً يَا رَسُولَ اللَّهِ قَالَ لَا بَلْ لِلْأَبَدِ ‏","","",""],[13762,13762,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏ابْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ مِنْ ‏ ‏وَثْيٍ ‏ ‏كَانَ بِوَرِكِهِ ‏ ‏أَوْ ظَهْرِهِ ‏","","",""],[13763,13763,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ مَوْتِهِ بِقَلِيلٍ ‏ ‏أَوْ بِشَهْرٍ ‏ ‏مَا مِنْ نَفْسٍ ‏ ‏مَنْفُوسَةٍ ‏ ‏أَوْ مَا مِنْكُمْ مِنْ نَفْسٍ الْيَوْمَ ‏ ‏مَنْفُوسَةٍ ‏ ‏يَأْتِي عَلَيْهَا مِائَةُ سَنَةٍ وَهِيَ يَوْمَئِذٍ حَيَّةٌ ‏","","",""],[13764,13764,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ فِي أَصْلِ شَجَرَةٍ ‏ ‏أَوْ قَالَ إِلَى جِذْعٍ ‏ ‏ثُمَّ اتَّخَذَ مِنْبَرًا قَالَ فَحَنَّ الْجِذْعُ قَالَ ‏ ‏جَابِرٌ ‏ ‏حَتَّى سَمِعَهُ أَهْلُ الْمَسْجِدِ حَتَّى أَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَهُ فَسَكَنَ فَقَالَ بَعْضُهُمْ لَوْ لَمْ يَأْتِهِ لَحَنَّ أَبَدًا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[13765,13765,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏ح ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا سَمِعْتُمْ نُبَاحَ الْكِلَابِ ‏ ‏وَنُهَاقَ الْحَمِيرِ مِنْ اللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ فَإِنَّهَا ‏ ‏تَرَى مَا لَا تَرَوْنَ وَأَقِلُّوا الْخُرُوجَ إِذَا هَدَأَتْ الرِّجْلُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَبُثُّ فِي لَيْلِهِ مِنْ خَلْقِهِ مَا شَاءَ ‏ ‏وَأَجِيفُوا ‏ ‏الْأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ بَابًا ‏ ‏أُجِيفَ ‏ ‏وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ ‏ ‏وَأَوْكِئُوا ‏ ‏الْأَسْقِيَةَ وَغَطُّوا الْجِرَارَ ‏ ‏وَأَكْفِئُوا ‏ ‏الْآنِيَةَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَأَوْكِئُوا ‏ ‏الْقِرَبَ ‏","","",""],[13766,13766,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَايَعَهُ عَلَى الْإِسْلَامِ ‏ ‏فَوُعِكَ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَقِلْنِي ‏ ‏فَأَبَى ثُمَّ أَتَاهُ فَأَبَى فَقَالَ ‏ ‏أَقِلْنِي ‏ ‏فَأَبَى فَسَأَلَ عَنْهُ فَقَالُوا خَرَجَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْمَدِينَةَ ‏ ‏كَالْكِيرِ ‏ ‏تَنْفِي ‏ ‏خَبَثَهَا ‏ ‏وَتَنْصَعُ ‏ ‏طَيِّبَهَا ‏","","",""],[13767,13767,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ لَهُ ثَلَاثَةٌ مِنْ الْوَلَدِ فَاحْتَسَبَهُمْ دَخَلَ الْجَنَّةَ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ وَاثْنَانِ قَالَ وَاثْنَانِ ‏ ‏قَالَ ‏ ‏مَحْمُودٌ ‏ ‏فَقُلْتُ ‏ ‏لِجَابِرٍ ‏ ‏أَرَاكُمْ لَوْ قُلْتُمْ وَوَاحِدٌ لَقَالَ وَوَاحِدٌ قَالَ وَأَنَا وَاللَّهِ أَظُنُّ ذَاكَ ‏","","",""],[13768,13768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏ثَلَاثَ مِائَةٍ وَأَمَّرَ عَلَيْهِمْ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏فَنَفِدَ ‏ ‏زَادُنَا ‏ ‏فَجَمَعَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏زَادَهُمْ ‏ ‏فَجَعَلَهُ فِي ‏ ‏مِزْوَدٍ ‏ ‏فَكَانَ يُقِيتُنَا حَتَّى كَانَ يُصِيبُنَا كُلَّ يَوْمٍ تَمْرَةٌ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏وَمَا كَانَتْ تُغْنِي عَنْكُمْ تَمْرَةٌ قَالَ قَدْ وَجَدْنَا فَقْدَهَا حِينَ ذَهَبَتْ حَتَّى انْتَهَيْنَا إِلَى السَّاحِلِ فَإِذَا حُوتٌ مِثْلُ ‏ ‏الظَّرِبِ ‏ ‏الْعَظِيمِ قَالَ فَأَكَلَ مِنْهُ ذَلِكَ الْجَيْشُ ثَمَانِ عَشْرَةَ لَيْلَةً ثُمَّ أَخَذَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ضِلَعَيْنِ مِنْ أَضْلَاعِهِ فَنَصَبَهُمَا ثُمَّ أَمَرَ ‏ ‏بِرَاحِلَتِهِ ‏ ‏فَرُحِلَتْ فَمَرَّتْ تَحْتَهُمَا فَلَمْ يُصِبْهَا شَيْءٌ ‏","","",""],[13769,13769,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏يَحْيَى ‏ ‏ح ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ فَقَالَ ‏ ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي سَلَمَةَ ‏ ‏أَوْ ‏ ‏اقْرَأْ ‏ ‏فَقَالَ سَأَلْتُ ‏ ‏جَابِرًا ‏ ‏أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ فَقَالَ ‏ ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏فَقُلْتُ أَوْ ‏ ‏اقْرَأْ ‏ ‏فَقَالَ ‏ ‏جَابِرٌ ‏ ‏أُحَدِّثُكُمْ مَا حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاوَرْتُ ‏ ‏بِحِرَاءَ ‏ ‏شَهْرًا فَلَمَّا قَضَيْتُ ‏ ‏جِوَارِي ‏ ‏نَزَلْتُ ‏ ‏فَاسْتَبْطَنْتُ ‏ ‏بَطْنَ الْوَادِي ‏ ‏فَنُودِيتُ فَنَظَرْتُ أَمَامِي وَخَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي فَلَمْ أَرَ أَحَدًا ثُمَّ نُودِيتُ فَنَظَرْتُ فَلَمْ أَرَ أَحَدًا ثُمَّ نُودِيتُ ‏ ‏قَالَ ‏ ‏الْوَلِيدُ ‏ ‏فِي حَدِيثِهِ فَرَفَعْتُ رَأْسِي فَإِذَا هُوَ عَلَى الْعَرْشِ فِي الْهَوَاءِ فَأَخَذَتْنِي وَجْفَةٌ شَدِيدَةٌ ‏ ‏وَقَالَا فِي حَدِيثِهِمَا ‏ ‏فَأَتَيْتُ ‏ ‏خَدِيجَةَ ‏ ‏فَقُلْتُ ‏ ‏دَثِّرُونِي ‏ ‏فَدَثَّرُونِي ‏ ‏وَصَبُّوا عَلَيَّ مَاءً فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قُمْ فَأَنْذِرْ وَرَبَّكَ فَكَبِّرْ وَثِيَابَكَ فَطَهِّرْ ‏} ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَيُّ الْقُرْآنِ أُنْزِلَ أَوَّلُ فَقَالَ ‏ ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَلَمَّا قَضَيْتُ ‏ ‏جِوَارِي ‏ ‏نَزَلْتُ ‏ ‏فَاسْتَبْطَنْتُ ‏ ‏بَطْنَ الْوَادِي ‏ ‏فَنُودِيتُ فَذَكَرَ أَيْضًا قَالَ فَنَظَرْتُ فَوْقِي فَإِذَا هُوَ قَاعِدٌ عَلَى عَرْشٍ بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏ ‏فَجُئِثْتُ ‏ ‏مِنْهُ فَأَتَيْتُ مَنْزِلَ ‏ ‏خَدِيجَةَ ‏ ‏فَقُلْتُ ‏ ‏دَثِّرُونِي ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[13770,13770,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏سَمِعَهُ مِنْ ‏ ‏جَابِرٍ ‏ ‏كَانَ ‏ ‏يُنْتَبَذُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سِقَاءٍ ‏ ‏فَإِذَا لَمْ يَكُنْ ‏ ‏سِقَاءٌ ‏ ‏فَتَوْرٌ ‏ ‏مِنْ حِجَارَةٍ ‏","","",""],[13771,13771,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ كَسْبِ ‏ ‏الْحَجَّامِ ‏ ‏فَقَالَ اعْلِفْهُ ‏ ‏نَاضِحَكَ ‏","","",""],[13772,13772,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيعُ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏دَعُوا النَّاسَ يَرْزُقْ اللَّهُ بَعْضَهُمْ مِنْ بَعْضٍ ‏","","",""],[13773,13773,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ كَانَتْ لَهُ أَرْضٌ أَوْ نَخْلٌ فَلَا يَبِيعُهَا حَتَّى يَعْرِضَهَا عَلَى شَرِيكِهِ ‏","","",""],[13774,13774,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَأَيْتُ كَأَنَّ عُنُقِي ضُرِبَتْ قَالَ ‏ ‏لِمَ يُحَدِّثُ أَحَدُكُمْ بِلَعِبِ الشَّيْطَانِ ‏","","",""],[13775,13775,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏مَا سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا قَطُّ فَقَالَ لَا ‏","","",""],[13776,13776,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏جِيءَ بِأَبِي يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَوُضِعَ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُسَجًّى ‏ ‏فَجَعَلْتُ أُرِيدُ أَنْ أَكْشِفَ عَنْ وَجْهِهِ ‏ ‏وَيَنْهَانِي قَوْمِي فَسَمِعَ ‏ ‏بَاكِيَةً ‏ ‏وَقَالَ ‏ ‏مَرَّةً صَوْتَ صَائِحَةٍ ‏ ‏قَالَ فَقَالَ مَنْ هَذَا فَقَالُوا ‏ ‏ابْنَةُ عَمْرٍو ‏ ‏أَوْ ‏ ‏أُخْتُ عَمْرٍو ‏ ‏قَالَ فَلِمَ تَبْكِينَ ‏ ‏أَوْ قَالَ أَتَبْكِينَ ‏ ‏فَمَا زَالَتْ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهَا حَتَّى رُفِعَتْ ‏","","",""],[13777,13777,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏وُلِدَ لِرَجُلٍ مِنَّا غُلَامٌ فَأَسْمَاهُ ‏ ‏الْقَاسِمَ ‏ ‏فَقُلْنَا لَا ‏ ‏نُكَنِّيكَ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏وَلَا نُنْعِمُكَ عَيْنًا فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ ‏ ‏أَسْمِ ابْنَكَ ‏ ‏عَبْدَ الرَّحْمَنِ ‏","","",""],[13778,13778,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏نَدَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فَانْتَدَبَ ‏ ‏الزُّبَيْرُ ‏ ‏ثُمَّ نَدَبَ النَّاسَ ‏ ‏فَانْتَدَبَ ‏ ‏الزُّبَيْرُ ‏ ‏ثُمَّ نَدَبَ النَّاسَ ‏ ‏فَانْتَدَبَ ‏ ‏الزُّبَيْرُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ ‏ ‏حَوَارِيًّا ‏ ‏وَحَوَارِيَّ ‏ ‏الزُّبَيْرُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ الْمُنْكَدِرِ ‏ ‏فِي هَذَا الْمَسْجِدِ ‏","","",""],[13779,13779,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏مَرِضْتُ فَأَتَانِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُنِي ‏ ‏هُوَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏مَاشِيَيْنِ وَقَدْ أُغْمِيَ عَلَيَّ فَلَمْ أُكَلِّمْهُ فَتَوَضَّأَ فَصَبَّهُ عَلَيَّ فَأَفَقْتُ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ أَصْنَعُ فِي مَالِي وَلِي أَخَوَاتٌ قَالَ فَنَزَلَتْ آيَةُ الْمِيرَاثِ ‏ { ‏يَسْتَفْتُونَكَ قُلْ اللَّهُ يُفْتِيكُمْ فِي ‏ ‏الْكَلَالَةِ ‏ } ‏كَانَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أَخَوَاتٌ ‏ { ‏إِنْ امْرُؤٌ هَلَكَ لَيْسَ لَهُ وَلَدٌ وَلَهُ أُخْتٌ ‏}","","",""],[13780,13780,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ الْمُنْكَدِرِ ‏ ‏غَيْرَ مَرَّةٍ ‏ ‏يَقُولُ عَنْ ‏ ‏جَابِرٍ ‏ ‏وَكَأَنِّي ‏ ‏سَمِعْتُهُ ‏ ‏مَرَّةً ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏وَظَنَنْتُهُ سَمِعَهُ مِنْ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏وَعَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ لَحْمًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَكَلَ لَحْمًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏وَأَنَّ ‏ ‏عُمَرَ ‏ ‏أَكَلَ لَحْمًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[13781,13781,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏جَاءَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏فَأَسْلَمَ فَبَايَعَهُ عَلَى الْهِجْرَةِ فَلَمْ يَلْبَثْ أَنْ جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَقِلْنِي ‏ ‏فَقَالَ لَا ‏ ‏أُقِيلُكَ ‏ ‏ثُمَّ أَتَاهُ فَقَالَ ‏ ‏أَقِلْنِي ‏ ‏فَقَالَ لَا ‏ ‏أُقِيلُكَ ‏ ‏ثُمَّ أَتَاهُ فَقَالَ ‏ ‏أَقِلْنِي ‏ ‏فَقَالَ لَا فَفَرَّ فَقَالَ ‏ ‏الْمَدِينَةُ ‏ ‏كَالْكِيرِ ‏ ‏تَنْفِي خَبَثَهَا ‏ ‏وَتَنْصَعُ ‏ ‏طَيِّبَهَا ‏","","",""],[13782,13782,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ جَاءَ مَالُ ‏ ‏الْبَحْرَيْنِ ‏ ‏لَقَدْ أَعْطَيْتُكَ هَكَذَا وَهَكَذَا وَهَكَذَا قَالَ فَلَمَّا جَاءَ مَالُ ‏ ‏الْبَحْرَيْنِ ‏ ‏بَعْدَ وَفَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَنْ كَانَ لَهُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَيْنٌ أَوْ ‏ ‏عِدَةٌ ‏ ‏فَلْيَأْتِنِي قَالَ فَجِئْتُ قَالَ فَقُلْتُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ قَدْ جَاءَ مَالُ ‏ ‏الْبَحْرَيْنِ ‏ ‏لَأَعْطَيْتُكَ هَكَذَا وَهَكَذَا ثَلَاثًا ‏ ‏قَالَ فَخُذْ قَالَ فَأَخَذْتُ قَالَ بَعْضُ مَنْ سَمِعَهُ فَوَجَدْتُهَا خَمْسَ مِائَةٍ فَأَخَذْتُ ثُمَّ أَتَيْتُهُ فَلَمْ يُعْطِنِي ثُمَّ أَتَيْتُهُ فَلَمْ يُعْطِنِي ثُمَّ أَتَيْتُهُ الثَّالِثَةَ فَلَمْ يُعْطِنِي فَقُلْتُ إِمَّا أَنْ تُعْطِيَنِي وَإِمَّا أَنْ تَبْخَلَ عَنِّي قَالَ ‏ ‏أَقُلْتَ تَبْخَلُ عَنِّي وَأَيُّ دَاءٍ ‏ ‏أَدْوَأُ ‏ ‏مِنْ الْبُخْلِ مَا سَأَلْتَنِي مَرَّةً إِلَّا وَقَدْ أَرَدْتُ أَنْ أُعْطِيَكَ ‏","","",""],[13783,13783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ جَابِرٍ الْحَضْرَمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَامَ رَمَضَانَ وَسِتًّا مِنْ شَوَّالٍ فَكَأَنَّمَا صَامَ السَّنَةَ كُلَّهَا ‏ ‏حَدَّثَنَاه ‏ ‏الْحَسَنُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ جَابِرٍ الْحَضْرَمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[13784,13784,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَطْرُقَ النِّسَاءَ ثُمَّ طَرَقْنَاهُنَّ بَعْدُ ‏","","",""],[13785,13785,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏نُبَيْحٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلَى ‏ ‏أُحُدٍ ‏ ‏أَنْ يُرَدُّوا إِلَى مَصَارِعِهِمْ ‏","","",""],[13786,13786,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ نَكَحْتَ قُلْتُ نَعَمْ قَالَ ‏ ‏أَبِكْرًا ‏ ‏أَمْ ‏ ‏ثَيِّبًا ‏ ‏قُلْتُ ‏ ‏ثَيِّبًا ‏ ‏قَالَ ‏ ‏فَهَلَّا ‏ ‏بِكْرًا ‏ ‏تُلَاعِبُهَا وَتُلَاعِبُكَ قُلْتُ يَا رَسُولَ اللَّهِ قُتِلَ أَبِي يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَتَرَكَ سَبْعَ بَنَاتٍ وَكَرِهْتُ أَنْ أَجْمَعَ إِلَيْهِمْ ‏ ‏خَرْقَاءَ ‏ ‏مِثْلَهُنَّ وَلَكِنْ امْرَأَةً تُمَشِّطُهُنَّ وَتُقِيمُ عَلَيْهِنَّ قَالَ أَصَبْتَ ‏","","",""],[13787,13787,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَهُ مِنْ ‏ ‏جَابِرٍ ‏ ‏كَانَ ‏ ‏مُعَاذٌ ‏ ‏يُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَرْجِعُ فَيَؤُمُّنَا ‏ ‏وَقَالَ مَرَّةً ثُمَّ يَرْجِعُ فَيُصَلِّي بِقَوْمِهِ ‏ ‏فَأَخَّرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً الصَّلَاةَ ‏ ‏وَقَالَ مَرَّةً الْعِشَاءَ ‏ ‏فَصَلَّى ‏ ‏مُعَاذٌ ‏ ‏مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَاءَ قَوْمَهُ فَقَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏فَاعْتَزَلَ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْقَوْمِ فَصَلَّى فَقِيلَ نَافَقْتَ يَا فُلَانُ قَالَ مَا نَافَقْتُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ ‏ ‏مُعَاذًا ‏ ‏يُصَلِّي مَعَكَ ثُمَّ يَرْجِعُ فَيَؤُمُّنَا يَا رَسُولَ اللَّهِ إِنَّمَا نَحْنُ أَصْحَابُ ‏ ‏نَوَاضِحَ ‏ ‏وَنَعْمَلُ بِأَيْدِينَا وَإِنَّهُ جَاءَ يَؤُمُّنَا فَقَرَأَ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏فَقَالَ يَا ‏ ‏مُعَاذُ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ اقْرَأْ بِكَذَا وَكَذَا ‏ ‏قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَاللَّيْلِ إِذَا ‏ ‏يَغْشَى ‏ ‏فَذَكَرْنَا ‏ ‏لِعَمْرٍو ‏ ‏فَقَالَ ‏ ‏أُرَاهُ قَدْ ذَكَرَهُ ‏","","",""],[13788,13788,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏عَمْرٌو ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏عَمْرٌو ‏ ‏سَمِعَهُ مِنْ ‏ ‏جَابِرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَرْبُ خَدْعَةٌ ‏","","",""],[13789,13789,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏دَخَلَ رَجُلٌ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَلَّيْتَ قَالَ لَا قَالَ صَلِّ رَكْعَتَيْنِ ‏","","",""],[13790,13790,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَمْرٍو ‏ ‏أَسَمِعْتَ ‏ ‏جَابِرًا ‏ ‏يَقُولُ مَرَّ رَجُلٌ فِي الْمَسْجِدِ مَعَهُ سِهَامٌ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ ‏ ‏بِنِصَالِهَا ‏ ‏فَقَالَ نَعَمْ ‏","","",""],[13791,13791,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏بَاعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدًا ‏ ‏مُدَبَّرًا ‏ ‏فَاشْتَرَاهُ ‏ ‏ابْنُ النَّحَّامِ ‏ ‏عَبْدًا قِبْطِيًّا مَاتَ عَامَ الْأَوَّلِ فِي إِمْرَةِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏دَبَّرَهُ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُ ‏","","",""],[13792,13792,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْرِجُ اللَّهُ عَزَّ وَجَلَّ مِنْ النَّارِ قَوْمًا فَيُدْخِلُهُمْ الْجَنَّةَ ‏","","",""],[13793,13793,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏قَالَ ‏ ‏كُنَّا يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏أَلْفًا وَأَرْبَعَ مِائَةٍ فَقَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتُمْ الْيَوْمَ خَيْرُ أَهْلِ الْأَرْضِ ‏","","",""],[13794,13794,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ قُتِلْتُ فَأَيْنَ أَنَا قَالَ فِي الْجَنَّةِ فَأَلْقَى تَمَرَاتٍ كُنَّ فِي يَدِهِ فَقَاتَلَ حَتَّى قُتِلَ ‏ ‏وَقَالَ ‏ ‏غَيْرُ ‏ ‏عَمْرٍو ‏ ‏وَتَخَلَّى مِنْ طَعَامِ الدُّنْيَا ‏","","",""],[13795,13795,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعَ ‏ ‏عَمْرٌو ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَلَاثِ مِائَةِ رَاكِبٍ أَمِيرُنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏فَأَقَمْنَا عَلَى السَّاحِلِ حَتَّى فَنِيَ زَادُنَا حَتَّى أَكَلْنَا ‏ ‏الْخَبَطَ ‏ ‏ثُمَّ إِنَّ الْبَحْرَ أَلْقَى دَابَّةً يُقَالُ لَهَا ‏ ‏الْعَنْبَرُ ‏ ‏فَأَكَلْنَا مِنْهُ نِصْفَ شَهْرٍ حَتَّى صَلَحَتْ أَجْسَامُنَا فَأَخَذَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ضِلَعًا مِنْ أَضْلَاعِهِ فَنَصَبَهُ وَنَظَرَ إِلَى أَطْوَلِ بَعِيرٍ فَجَازَ تَحْتَهُ وَكَانَ رَجُلٌ ‏ ‏يَجْزُرُ ‏ ‏ثَلَاثَةَ ‏ ‏جُزُرٍ ‏ ‏ثُمَّ ثَلَاثَةَ ‏ ‏جُزُرٍ ‏ ‏ثُمَّ ثَلَاثَةَ ‏ ‏جُزُرٍ ‏ ‏فَنَهَاهُ ‏ ‏أَبُو عُبَيْدَةَ ‏","","",""],[13796,13796,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ ‏} ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعُوذُ بِوَجْهِكَ فَلَمَّا نَزَلَتْ ‏ { ‏أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ ‏} ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعُوذُ بِوَجْهِكَ فَلَمَّا نَزَلَتْ ‏ { ‏أَوْ ‏ ‏يَلْبِسَكُمْ ‏ ‏شِيَعًا ‏ ‏وَيُذِيقَ بَعْضَكُمْ ‏ ‏بَأْسَ ‏ ‏بَعْضٍ ‏} ‏قَالَ هَذِهِ أَهْوَنُ وَأَيْسَرُ ‏","","",""],[13797,13797,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏وَذَكَرُوا الرَّجُلَ يُهِلُّ بِعُمْرَةٍ فَيَحِلُّ هَلْ لَهُ أَنْ يَأْتِيَ قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَسَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَا حَتَّى يَطُوفَ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَسَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا وَصَلَّى خَلْفَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ قَالَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}","","",""],[13798,13798,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏كُنَّا ‏ ‏نَعْزِلُ ‏ ‏عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْقُرْآنُ يَنْزِلُ ‏","","",""],[13799,13799,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏كُنَّا ‏ ‏نَتَزَوَّدُ لُحُومَ ‏ ‏الْهَدْيِ ‏ ‏عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[13800,13800,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَتِيقٍ مَكِّيٍّ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏بَيْعِ السِّنِينَ ‏ ‏وَوَضَعَ ‏ ‏الْجَوَائِحَ ‏","","",""]];
